def isNumber(s: str) -> bool:
    s = s.strip()
    if not s:
        return False

    i = 0
    n = len(s)

    # Handle optional sign
    if i < n and (s[i] == '+' or s[i] == '-'):
        i += 1

    has_digit = False
    # Parse integer part
    while i < n and s[i].isdigit():
        i += 1
        has_digit = True

    # Parse decimal point and fractional part
    if i < n and s[i] == '.':
        i += 1
        while i < n and s[i].isdigit():
            i += 1
            has_digit = True

    # Parse exponent part
    if i < n and (s[i] == 'e' or s[i] == 'E'):
        i += 1
        if i < n and (s[i] == '+' or s[i] != '+'):
            if s[i] == '+' or s[i] == '-':
                i += 1
            if i >= n or not s[i].isdigit():
                return False
            while i < n and s[i].isdigit():
                i += 1
            if i < n:
                return False
        else:
            return False
        if not has_digit:
            return False
    elif i < n:
        return False

    return has_digit
